function shortestBeautifulSubstring(s, k) {
  let best = '';
  let left = 0;
  let ones = 0;
  for (let right = 0; right < s.length; right++) {
    if (s[right] === '1') {
      ones++;
    }
    while (ones > k || (left < right && s[left] === '0')) {
      if (s[left] === '1') {
        ones--;
      }
      left++;
    }
    if (ones === k) {
      const candidate = s.slice(left, right + 1);
      const shorter = best === '' || candidate.length < best.length;
      if (shorter || (candidate.length === best.length && candidate < best)) {
        best = candidate;
      }
    }
  }
  return best;
}

