function shortestBeautifulSubstring(s, k) {
  const found = [];
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) {
      const part = s.substring(i, j);
      if (part.split('').filter(c => c === '1').length === k) found.push(part);
    }
  }
  if (found.length === 0) return '';
  found.sort((a, b) => a.length - b.length || (a < b ? -1 : a > b ? 1 : 0));
  return found[0];
}

