function generate(rand, size) {
  const n = size === 'large' ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 10);
  const density = 0.05 + rand() * 0.9;
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < density ? '1' : '0';
  let ones = 0;
  for (const c of s) if (c === '1') ones++;
  // Usually ask for a reachable count of ones; sometimes ask for more than s has.
  const k = rand() < 0.85 && ones > 0 ? 1 + Math.floor(rand() * ones) : 1 + Math.floor(rand() * n);
  return [s, k];
}
